by
  cases h with c d;
  have h1 : b > 2 := hb;
  have h2 : a > b := ha;
  have h3 : a * b = 12 := h;
  have h4 : b ∈ {3, 4, 6, 12} :=
    by
      intro h5;
      rw [h5] at h3;
      cases h5;
      exact ⟨3, 4, 6, 12⟩
  rcases h4 with (| | | |);
  · rw [h3]; exact rfl;
  · rw [h3]; contradiction;
  · rw [h3]; contradiction;
  · rw [h3]; contradiction;
